+ 'var xn=[];var yn=[];for(var x=30;x<=115;x+=0.5){xn.push(x);yn.push(n*0.5/(sigma*Math.sqrt(2*Math.PI))*Math.exp(-0.5*Math.pow((x-mu)/sigma,2)));}'
+ 'var t1={x:scores,type:"histogram",nbinsx:30,name:"Puanlar",marker:{color:"rgba(78,205,196,0.6)",line:{color:"rgba(78,205,196,0.9)",width:1}},opacity:0.7};'
+ 'var t2={x:xn,y:yn,type:"scatter",mode:"lines",name:"Normal PDF",line:{color:"#c8a96e",width:2.5}};'
